import os
import glob
import json

def load_prowler_json(output_dir="output"):
    # Look for the new .asff.json files generated by Prowler
    json_files = glob.glob(os.path.join(output_dir, "*.json*"))
    if not json_files:
        print("[!] No Prowler JSON output found in 'output/' directory.")
        return []

    latest_file = max(json_files, key=os.path.getmtime)
    print(f"[*] Reading findings from: {latest_file}")

    findings = []
    with open(latest_file, "r", encoding="utf-8") as f:
        content = f.read().strip()
        try:
            data = json.loads(content)
            if isinstance(data, list):
                findings = data
            elif isinstance(data, dict):
                findings = [data]
        except json.JSONDecodeError:
            for line in content.splitlines():
                line = line.strip()
                if line:
                    try:
                        findings.append(json.loads(line))
                    except json.JSONDecodeError:
                        continue
    return findings

def create_html_report():
    findings = load_prowler_json()
    if not findings:
        print("[!] No findings to report.")
        return

    table_rows = ""
    total_findings = 0
    fail_count = 0
    pass_count = 0

    for item in findings:
        total_findings += 1
        
        # Extract ASFF Format Data
        if "Compliance" in item:
            status = item["Compliance"].get("Status", "UNKNOWN").upper()
            raw_id = item.get("Id", "N/A")
            check_id = raw_id.split("/")[-1] if "/" in raw_id else raw_id
            description = item.get("Title", "No description provided")
            
            # Extract Severity for ASFF format
            if "Severity" in item and "Label" in item["Severity"]:
                severity = item["Severity"]["Label"].upper()
            else:
                severity = "INFORMATIONAL"
                
            resources = item.get("Resources", [])
            if resources:
                service = resources[0].get("Type", "N/A")
                region = resources[0].get("Region", "N/A")
            else:
                service = "N/A"
                region = "N/A"
        # Fallback for old standard JSON format
        else:
            status = item.get("Status", item.get("status", "UNKNOWN")).upper()
            check_id = item.get("CheckID", item.get("check_id", "N/A"))
            service = item.get("ServiceName", item.get("service_name", "N/A"))
            region = item.get("Region", item.get("region", "N/A"))
            description = item.get("CheckTitle", item.get("check_title", item.get("StatusExtended", "No description provided")))
            severity = item.get("Severity", item.get("severity", "INFO")).upper()

        # Formatting colors for Pass/Fail Status
        if "FAIL" in status:
            fail_count += 1
            status_badge = "badge-fail"
        elif "PASS" in status:
            pass_count += 1
            status_badge = "badge-pass"
        else:
            status_badge = "badge-info"
            
        # Formatting colors for Severity
        if severity == "CRITICAL":
            sev_badge = "badge-critical"
        elif severity == "HIGH":
            sev_badge = "badge-high"
        elif severity == "MEDIUM":
            sev_badge = "badge-medium"
        elif severity == "LOW":
            sev_badge = "badge-low"
        else:
            sev_badge = "badge-info"

        # Note the data-severity attribute added to the <tr> for the JavaScript filter
        table_rows += f"""
        <tr data-severity="{severity}">
            <td><code>{check_id}</code></td>
            <td><span class="badge {status_badge}">{status}</span></td>
            <td><span class="badge {sev_badge}">{severity}</span></td>
            <td>{service}</td>
            <td>{region}</td>
            <td>{description}</td>
        </tr>
        """

    # HTML, CSS, and JS Template
    html_template = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cloud Audit - Prowler CIS Report</title>
    <style>
        body {{ font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background-color: #0f172a; color: #f8fafc; margin: 0; padding: 30px; }}
        .container {{ max-width: 1200px; margin: 0 auto; }}
        h1 {{ color: #38bdf8; margin-bottom: 5px; }}
        .header-controls {{ display: flex; justify-content: space-between; align-items: center; margin: 25px 0; }}
        .stats {{ display: flex; gap: 20px; }}
        .card {{ background: #1e293b; padding: 15px 25px; border-radius: 8px; border: 1px solid #334155; min-width: 140px; }}
        .card-num {{ font-size: 24px; font-weight: bold; color: #f8fafc; }}
        .filter-section select {{ padding: 8px 12px; background: #1e293b; color: #f8fafc; border: 1px solid #334155; border-radius: 6px; font-size: 14px; cursor: pointer; outline: none; }}
        table {{ width: 100%; border-collapse: collapse; background: #1e293b; border-radius: 8px; overflow: hidden; border: 1px solid #334155; }}
        th, td {{ padding: 12px 16px; text-align: left; border-bottom: 1px solid #334155; font-size: 14px; }}
        th {{ background: #0f172a; color: #94a3b8; text-transform: uppercase; font-size: 12px; letter-spacing: 0.05em; }}
        tr:hover {{ background: #334155; }}
        .badge {{ padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: bold; display: inline-block; text-align: center; min-width: 70px; }}
        .badge-fail {{ background-color: #ef4444; color: #ffffff; }}
        .badge-pass {{ background-color: #22c55e; color: #ffffff; }}
        .badge-critical {{ background-color: #7f1d1d; color: #fca5a5; border: 1px solid #b91c1c; }}
        .badge-high {{ background-color: #991b1b; color: #fecaca; border: 1px solid #ef4444; }}
        .badge-medium {{ background-color: #9a3412; color: #fed7aa; border: 1px solid #f97316; }}
        .badge-low {{ background-color: #854d0e; color: #fef08a; border: 1px solid #eab308; }}
        .badge-info {{ background-color: #334155; color: #cbd5e1; border: 1px solid #64748b; }}
        code {{ background: #0f172a; padding: 2px 6px; border-radius: 4px; color: #38bdf8; }}
    </style>
</head>
<body>
    <div class="container">
        <h1>Cloud Security Posture Audit</h1>
        <p style="color: #94a3b8;">Automated CIS Benchmark Assessment powered by Prowler</p>
        
        <div class="header-controls">
            <div class="stats">
                <div class="card">
                    <div style="color: #94a3b8; font-size: 12px;">TOTAL CHECKS</div>
                    <div class="card-num">{total_findings}</div>
                </div>
                <div class="card">
                    <div style="color: #ef4444; font-size: 12px;">FAILURES</div>
                    <div class="card-num" style="color: #ef4444;">{fail_count}</div>
                </div>
                <div class="card">
                    <div style="color: #22c55e; font-size: 12px;">PASSED</div>
                    <div class="card-num" style="color: #22c55e;">{pass_count}</div>
                </div>
            </div>
            
            <div class="filter-section">
                <label for="severityFilter" style="color: #94a3b8; margin-right: 10px;">Filter by Severity:</label>
                <select id="severityFilter" onchange="filterTable()">
                    <option value="ALL">All Severities</option>
                    <option value="CRITICAL">Critical</option>
                    <option value="HIGH">High</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="LOW">Low</option>
                    <option value="INFORMATIONAL">Informational</option>
                </select>
            </div>
        </div>

        <table>
            <thead>
                <tr>
                    <th>Check ID</th>
                    <th>Status</th>
                    <th>Severity</th>
                    <th>Service Type</th>
                    <th>Region</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                {table_rows}
            </tbody>
        </table>
    </div>

    <!-- JavaScript for handling the dropdown filter -->
    <script>
        function filterTable() {{
            var filter = document.getElementById("severityFilter").value;
            var rows = document.querySelectorAll("tbody tr");
            
            rows.forEach(row => {{
                var severity = row.getAttribute("data-severity");
                // If filter is set to ALL or matches the row's severity, show it. Otherwise, hide it.
                if (filter === "ALL" || severity === filter) {{
                    row.style.display = "";
                }} else {{
                    row.style.display = "none";
                }}
            }});
        }}
    </script>
</body>
</html>
"""
    output_html_path = "custom_report.html"
    with open(output_html_path, "w", encoding="utf-8") as f:
        f.write(html_template)
    print(f"[+] Successfully generated custom report with severity filters: {output_html_path}")

if __name__ == "__main__":
    create_html_report()